from author_library import *
cards=[]
cards.append(compact('song_tianran','宋天然','宋天然是建筑工程师，也是温宝裕的舅舅，与外甥关系亲近。他负责一处小岛工程时，偶然在爆山石块上发现与自己设计相符的图像，因此求助卫斯理，原想解决一个专业判断与巧合之间的谜，后来却被情报机关误认作掌握重大军事秘密的人而扣押。石纹里出现的部署图是现象本身，不是他取得了敌方情报；获释后他仍愿提供石块和工地记录，但不愿再独自承受由此招来的危险。小纳提出酬劳并要求秘密合作，他明确拒绝，不是为了标榜清高，而是看出收下机构的钱就会被视作其中一员。他继续协助取样，报告石山不同层次的成分差别，最后提出一种与预知不同的假设：也许某种力量先定计划再执行，所以图纹看起来预示未来。这个想法震动众人，却仍只是解释模型，并未证明有可操纵的命运程序。卡片保留温和、务实与被卷入大局后的界限感；他可以耐心讨论怪想，也会为被要求瞒骗朋友而生气。工程和地质知识是实际本领，发现石纹不赋予预言、因果改写或支配工地所有爆破能量的个人战力。','《命运》继续工程与研究，提出计划论假设，未获得可控预知或命运力量','主角','完成工程并理解异常，同时维护不受情报机构收编的生活','温和耐心，习惯用图纸、化验和现场信息讨论问题','被秘密组织施压时警惕身份绑定，不愿以收钱换保密','可讨论多种解释，但设想与证实必须分开',[ab('建筑工程与现场分析','设计建筑、组织工程并依据取样化验比较岩层','须实际项目、人员和设备；爆破不是肉身攻击'),ab('异常资料整合','将石纹、照片和已知图像比对，提出可继续讨论的模型','石纹难以事前解读，不能任意预知，更未掌握命运执行能力')],[ev('064',157,170,'工程师及舅甥关系'),ev('064',287,417,'发现和求助'),ev('064',1260,1324,'获释与误认为间谍'),ev('064',1453,1475,'拒绝机构金钱和瞒骗'),ev('064',1773,1844,'化验与计划论假设')],profile='expert'))
cards.append(compact('wang_yufang','王玉芳','王玉芳将满十七岁，自幼常独自沉思、欢喜或流泪，父母看不懂她的心事。她告诉卫斯理等人，自己记得已故姐姐王玉芬的人生，十岁时突然恢复与敌家健的来生约定，从此查旧报、走访、登广告，在人群中寻找爱人。她害怕两家仍因旧事故互相怨恨，又担心没人相信，所以长期保守秘密；直到办法越来越少，才终于求助。她叙述事故时并非只要求被救，记忆中的自己曾让家健放手求生，而对方仍不愿放弃。最后她见到敌文同雕刻的玉像，确信家健在其中，愿意留下相伴，家健父母因此消解对她的恨。原文同时保留另一种解释：医生认为她从家庭故事和照片形成了认同，卫斯理相信的转世也没有完整可独立验证的中间过程。卡片以她真切的自我认知和行动为中心，王玉芬作为其主张的前世合并记录，不额外叠加两个身体。她没有可反复发动的转世术或灵魂定位，所谓人海一眼认出是强烈感觉，实际寻找多年。演绎允许坚定与脆弱并存，不能以爱情为由替所有旁人宣布事实，也不能只把她化成“守着玉像”的单一姿势。','《十七年》选择住敌家与家健玉像相伴；转世解释有支持与竞争假说，未确认可控通灵','主角','兑现自己记忆中的爱情约定，并让当前生活容纳这份身份感','沉思而敏感，主动查资料和寻找，害怕秘密招来阻挠','久寻不得时焦虑，认出玉像后坚定维护留居选择','强烈体验值得认真听取，但不能把感觉当可保证成功的定位能力',[ab('记忆与资料查证','能叙述所认定前世经历，并主动查报刊、登广告和研究转世资料','过渡过程完全空白，相关认同也有心理解释；不是全知历史记忆'),ab('亲密身份辨认的主观感应','相信爱人已经转世并在玉像前产生强烈确认','不能保证远程定位或辨认任何灵魂，终局没有客观通用检验')],[ev('065',31,45,'幼年表现和父母求助'),ev('065',667,755,'事故叙述及恢复记忆'),ev('065',758,807,'多年寻找和感应边界'),ev('065',975,1040,'认像、选择与竞争解释')],profile='ordinary',aliases=['王玉芬（自述前世）']))
cards.append(compact('di_jiajian','敌家健','敌家健是敌文同夫妇的独子，年轻时与王玉芬相爱，不算热情外露，却喜欢驾驶和速度。两人出游后发生事故，王玉芳后来以自述前世回忆说明，他接替不会驾车的玉芬，越开越快，又为避开衔猫的大猫扭车，最终冲下悬崖。事故现场有更明确的记录：他重伤勾住树枝和岩石，紧握玉芬，不肯让她独自跌落，最后二人因失血过多死亡，握住的双手始终难以分开。这样的坚持既令人动容，也不能抹去驾驶风险与没有成功救回两人的事实。他死后，父亲用十七年雕出真人大小的玉像，王玉芳最终把它认作再生的家健，旁人感到玉像神情似有改变，却没有确认它能走、说话或主动拥抱。卡片保存这种开放结局；为可行动参演，明确恢复最后生前人体并携带已知关系背景，而不把玉石硬度、灵魂不灭与青年肉身叠加。他可以因关心伴侣而做勇敢选择，也会因为逞快和过分相信自己而付代价，不应被浪漫结局改写成从不犯错、任何情况下都能救人的圣人。','《十七年》生前死亡，后疑寄于玉像且无法主动行动；部署恢复最后生前人体，玉像说仍保留未定','主角','与所爱的人相守，在险境中不愿独自放弃对方','平日感情含蓄，喜欢驾驶和速度','危急时紧握伴侣、尽力支撑，也可能无法跳出共同受困的局面','感情的坚定不取消身体与救援条件的极限',[ab('普通驾驶和应急支撑','具汽车驾驶经验，事故中重伤仍支撑伴侣等待救援','超速和突然避让仍造成事故；没有超人力量或永不松手的物理法则'),ab('玉像关联的终局经历','王玉芳认定其灵魂在玉像内，现场观察者觉得神情变化','不确认能移动、发声或操纵玉石，不能以灵魂经历免疫死亡')],[ev('065',551,599,'事故现场与死亡'),ev('065',667,730,'驾驶经过和约定的自述'),ev('065',954,1007,'玉像终局的观察界限')],profile='ordinary'))
cards[-1]['adaptations'].append({'change':'恢复最后生前人体作为参演形态，保留玉像疑似寄魂的终局记录。','reason':'原文玉像不能主动移动或说话，用户允许适度改编以支持演绎。','power_impact':'不叠加玉石硬度、不增添再生或任意转世能力。'})
cards.append(compact('di_wentong','敌文同','敌文同是技艺出色的玉雕家，能把翠玉蚱蜢的薄翼与细纹刻得令人惊叹，独子死去后却把几乎全部财产换成巨块白玉，用十七年雕刻家健全身像。他与妻子维持儿子喜欢的生活，靠陈长青的资助保住房屋和创作，手艺的完成无法填补一个活人不在的缺口。悲痛也曾使他极端偏执：他认定王玉芬拖累儿子，隐去事故中两人紧握不放的细节，甚至在医院试图用刀割开死者的手，遭旁人阻止。多年后，寻找家健的广告与陌生少女再次撩动希望，他求助、怀疑、发怒，都围绕不愿承认永久失去儿子。终局玉芳认出玉像，雕像似显新生气，他与妻子终于拥抱二者，放下对女孩的恨。卡片保留父爱与伤害并存，不把悲伤自动美化为公正判断。玉雕逼真是技术和投入，灵魂是否进入不是他能设计或重复发动的造人术；演绎时他可以通过具体雕刻和日常照料表达感情，也必须有空间承认过去把责任强加给别人。','《十七年》接受玉芳与家健玉像相伴，放下部分旧怨，仍为普通老年玉雕家','主角','保住与儿子的联系，并在失去后的生活中找到可以继续付出的对象','做工细致，常触摸雕像，谈儿子时由客套转为哽咽','悲痛受触动时可能固执指责，看到关系仍可延续时能够转向接纳','艺术不能替代活人，自己的哀痛也不能证明他人该受责备',[ab('高水平玉雕','长期雕琢细微结构与人体神态，完成极逼真的儿子像','需玉材、工具和时间；未证实可主动赋魂或创造生命'),ab('长期细节记忆','保存儿子相貌、习惯和相关资料，追查寻人广告','记忆与叙述受丧子情绪影响，曾隐去不利于自己归责的细节')],[ev('065',160,191,'技艺、十七年雕刻与资助'),ev('065',227,240,'日常哀伤'),ev('065',570,599,'隐去细节和割手行为'),ev('065',993,1010,'接纳和放下怨恨')],profile='expert'))
cards.append(compact('di_mother','敌太太','敌太太是家健的母亲，未满六十便满头白发，平常仍修剪花木、准备茶点，细细维持儿子喜欢的环境，仿佛他随时会回来。她与丈夫反复说若孩子活着该多少岁、是否已经有儿女，哀伤成了生活的主要节律。十周年忌日，一个陌生小女孩望着遗像落泪，她先开口询问，后来又想起这段怪事，提醒丈夫向卫斯理说明，成为重新追寻的线索。她同样深恨王玉芬，认为儿子被拖累；听见来生和再见的可能时，怨愤又迅速混合成希望、委屈和“为何不来看我们”的哭问。最后王玉芳认出玉像，她看到神情似有变化，与丈夫一起拥抱雕像和女孩，愿意接受二者的新关系。卡片不让她继承丈夫的玉雕技能，也不把母子感情变成灵魂雷达。她的力量是照料、记忆与仍可改变的情感，弱点则是把自己的失去全部解释成他人的责任。演绎应允许她有安静的日常、温柔待客和突发的尖锐，而非永远只在哭泣；接受新生活可以渐进，不必每场复述同一段悲剧。','《十七年》接受玉芳留居并将玉像视为儿子关系的延续，转世机制仍未证实','主角','维持对儿子的爱，并在新的关系中寻找陪伴','以花木、招待与生活习惯表达照顾，牢牢记得儿子的日期和喜好','失子话题触发怨恨和哭泣，但新的相认证据能使她重新接纳','思念可以保留，不能永远要求别人为自己的丧失受罚',[ab('家庭记忆与照料','记得儿子生活细节，观察并报告奇怪小女孩的来访','不是读取灵魂或自动认定转世的能力'),ab('关系修复','在最终场景放下对玉芳的恨并接纳留居','依赖具体经历和本人意愿，不是强制安抚他人的精神术')],[ev('065',199,240,'外形、日常与丧子情感'),ev('065',342,393,'少女来访的记忆'),ev('065',930,1007,'痛哭与最终接纳')],profile='ordinary'))
cards.append(compact('wang_zhenqiang','王振强','王振强是电机工程师，接近退休，原本更愿相信现代科学能够验证的解释。他与妻子先失去王玉芬，又看见小女儿玉芳从幼年起沉思、喜怒和流泪难以理解，亲人的异常把他从惯常的理性立场推向求助。两人写信给卫斯理，希望弄清孩子内心，既有对陌生现象的不安，也有无法再承受一次失女的恐惧。在旧事故中，王家曾提议让至死握手的两名年轻人合葬，后来与敌家彼此归责，悲痛没有因为共同失去便自然转成和解。玉芳决定住到敌家，把玉像认作丈夫时，他和妻子坚决反对、多次争吵，又安排专业人员检查；最终女儿坚持自愿，两人才停止强逼回家，问题并未变成全家一致理解的圆满结局。卡片保留工程背景和一个父亲的保护欲，同时不把科学怀疑等同冷酷，也不把爱女变成可以无限控制她的授权。电机知识是职业经验，不能因此破解灵魂与记忆；在新情境中他会寻求可验证的解释和可信帮助，也需面对女儿已经有自己选择的事实。','《十七年》停止强逼玉芳回家，但对玉像婚姻与转世仍不接受，未确认家庭完全和解','主角','保护在世女儿，避免再次失去孩子并理解其异常经历','习惯技术性解释，谨慎求证，遇家事愿与妻子共同求助','女儿选择令他恐惧时转为强硬和反复检查，最终被其坚持迫使让步','怀疑并不使体验不存在，关心也应承认当事人的意愿',[ab('电机工程知识','有长期电机工程职业背景','未展示特殊武器或外星工程，不扩写为全能科学'),ab('求助与家庭协调','与妻子写信、寻找解释并请专业者检查女儿','他人评估并不能保证揭开故事中的全部机制')],[ev('065',31,45,'职业与共同求助'),ev('065',590,616,'姓名及旧事故态度'),ev('065',1011,1040,'反对留居与检查结果')],profile='expert'))
cards.append(compact('zhao_ziling','赵自玲','赵自玲是王玉芬、王玉芳的母亲，她写给卫斯理的信以一个不知如何才好的妈妈署名，语气先埋怨对方总帮助外星人，再恳切说明家庭困境，希望引起重视。她细察小女儿从幼年起的沉思、笑容和泪水，却不能进入那套私人记忆；曾失去长女的痛，使每一种新的怪行为都像可能再次失去孩子的征兆。她与丈夫共同求助，也曾在旧事故后提议让紧握不放的恋人合葬，但两个家庭后来互生怨恨，温柔与愤怒并存。玉芳终于说出转世说并住到敌家，与雕像相伴，赵自玲难以接受，她与丈夫前去争吵、寻求医生检查，希望把孩子带回熟悉的生活。终局他们停止强逼，却没有确认相信玉芳所说的一切。卡片保留一个会写信、观察、争取援助又可能因恐惧越界的母亲，不把她简单归类成阻挠爱情的坏人，也不赋予母性必能识别灵魂的超能。新的场景中，她可以先问孩子具体遭遇、寻找沟通方法，同时需要学习并非每一份无法理解的选择都等于女儿即将消失。','《十七年》停止强逼女儿离开敌家，仍不相信其解释，后续和解程度未明','主角','保住女儿的安全与联系，并让外人认真帮助这个家庭','观察细致，写信恳切中带急切埋怨，重视家庭往事','失女恐惧被触发时多次争论和求检查，仍可能在女儿坚持后退让','保护应从具体危险出发，不能只因不理解便取消女儿表达自己的权利',[ab('长期家庭观察','记录女儿幼年起的行为变化并向调查者提供线索','只能观察表现，不能直接读懂前世或保证自己的解释正确'),ab('主动求助与沟通','持续写信、联络帮助并为家庭争取关注','说服需要他人回应，不是情感控制或无条件资源调用')],[ev('065',15,45,'母亲来信和长期观察'),ev('065',590,616,'姓名与丧女背景'),ev('065',1011,1016,'终局反对和停止强逼')],profile='ordinary'))
save(cards)
